'"

/bin/bash -lc "python - <<'PY'
import json, urllib.request
base='https://quay.io/api/v1/repository/biocontainers/anndata/tag/?onlyActiveTags=true&limit=100&page='
for p in range(1,20):
    d=json.load(urllib.request.urlopen(base+str(p)))
    for t in d.get('tags',[]):
        if t['name'].startswith('0.11.4'):
            print(t['name'])
    if not d.get('has_additional'):
        break
PY"

